#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::*;
use crate::domain::observation::{Origin, ToolEffect};

#[test]
fn harness_prompts_are_marked_and_unknown_prefixes_count_as_the_user() {
    assert_eq!(
        prompt_origin("<task-notification>done</task-notification>"),
        Origin::Harness
    );
    assert_eq!(
        prompt_origin("<local-command-stdout>ok</local-command-stdout>"),
        Origin::Harness
    );
    assert_eq!(
        prompt_origin(
            "Caveat: The messages below were generated by the user while running local commands."
        ),
        Origin::Harness
    );
    assert_eq!(prompt_origin("<something-new>x"), Origin::User);
    assert_eq!(prompt_origin("please refactor"), Origin::User);
}

#[test]
fn tools_are_classified_failed_then_read_then_write_with_unknown_bash_as_write() {
    let none = serde_json::json!({});
    let bash = |command: &str| serde_json::json!({ "command": command });
    assert_eq!(tool_effect("Read", &none, false), ToolEffect::Reads);
    assert_eq!(
        tool_effect("mcp__acme-ivar__graph_explore", &none, false),
        ToolEffect::Reads
    );
    assert_eq!(tool_effect("glob", &none, false), ToolEffect::Reads);
    assert_eq!(tool_effect("list", &none, false), ToolEffect::Reads);
    assert_eq!(tool_effect("Edit", &none, false), ToolEffect::Writes);
    assert_eq!(tool_effect("Read", &none, true), ToolEffect::Failed);
    assert_eq!(
        tool_effect("Bash", &bash("git status"), false),
        ToolEffect::Reads
    );
    assert_eq!(
        tool_effect("Bash", &bash("make deploy"), false),
        ToolEffect::Writes
    );
    assert_eq!(
        tool_effect("Bash", &bash("cat a > b"), false),
        ToolEffect::Writes
    );
    assert_eq!(
        tool_effect("Bash", &bash("ls && rm -rf x"), false),
        ToolEffect::Writes
    );
    assert_eq!(
        tool_effect("Bash", &bash("find . -name x -delete"), false),
        ToolEffect::Writes
    );
    assert_eq!(tool_effect("Bash", &none, false), ToolEffect::Writes);
}

#[test]
fn memory_reads_are_reads_and_memory_writes_are_writes_under_both_name_styles() {
    let none = serde_json::json!({});
    for name in [
        "memory_query",
        "mcp__acme-ivar__memory_query",
        "acme-ivar_memory_read_page",
        "mcp__acme-ivar__memory_lint",
        "acme-ivar_memory_status",
        "mcp__acme-ivar__memory_recent",
        "acme-ivar_memory_read_session_observations",
    ] {
        assert_eq!(tool_effect(name, &none, false), ToolEffect::Reads, "{name}");
    }
    for name in [
        "mcp__acme-ivar__memory_write_page",
        "acme-ivar_memory_patch_page",
        "mcp__acme-ivar__memory_delete_page",
    ] {
        assert_eq!(
            tool_effect(name, &none, false),
            ToolEffect::Writes,
            "{name}"
        );
    }
    assert_eq!(tool_effect("memory_query", &none, true), ToolEffect::Failed);
}

#[test]
fn read_only_tools_record_only_name_and_path() {
    let body = tool_body(
        "Read",
        &serde_json::json!({"file_path":"/hall/a.rs","limit":50}),
        ToolEffect::Reads,
        Some("fn main() {}"),
    );
    assert!(body.contains("Read") && body.contains("/hall/a.rs"));
    assert!(
        !body.contains("fn main"),
        "file contents must not be stored: {body}"
    );
}

#[test]
fn listing_handoffs_is_a_read_and_the_other_handoff_tools_are_writes() {
    let none = serde_json::json!({});
    assert_eq!(
        tool_effect("mcp__acme-ivar__memory_handoff_list", &none, false),
        ToolEffect::Reads
    );
    for tool in [
        "memory_handoff_begin",
        "memory_handoff_accept",
        "memory_handoff_cancel",
    ] {
        assert_eq!(
            tool_effect(&format!("mcp__acme-ivar__{tool}"), &none, false),
            ToolEffect::Writes,
            "{tool}"
        );
    }
}

#[test]
fn a_message_list_call_is_a_memory_read() {
    let input = serde_json::json!({});
    assert_eq!(
        tool_effect("mcp__hall-ivar__memory_message_list", &input, false),
        ToolEffect::Reads
    );
    assert_ne!(
        tool_effect("mcp__hall-ivar__memory_message_pop", &input, false),
        ToolEffect::Reads
    );
}
